public class FitnessTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        check("score(\"hello\", \"hello\")", 5, Fitness.score("hello", "hello"));
        check("score(\"hxllo\", \"hello\")", 4, Fitness.score("hxllo", "hello"));
        check("score(\"abc\", \"xyz\")", 0, Fitness.score("abc", "xyz"));
        check("score(\"abcdef\", \"abc\") -- candidate longer", 3, Fitness.score("abcdef", "abc"));
        check("score(\"axc\", \"abcde\") -- target longer", 2, Fitness.score("axc", "abcde"));
        check("score(\"\", \"abc\") -- empty candidate", 0, Fitness.score("", "abc"));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

