public class Fitness {

    public static int score(String candidate, String target) {
        int limit = Math.min(candidate.length(), target.length());
        int matches = 0;
        for (int i = 0; i < limit; i++) {
            if (candidate.charAt(i) == target.charAt(i)) {
                matches++;
            }
        }
        return matches;
    }
}
